-- NEXORA FORGE ACADEMY: publish the six intermediate and advanced courses
-- Safe to run once; upserts by stable IDs and preserves the 58 existing beginner lessons.
begin;
insert into public.academy_courses(id,language_id,level_id,title,slug,description,status,sort_order,estimated_hours)
select x.id,x.language_id,x.level_id,x.title,x.slug,x.description,x.status,x.sort_order,x.estimated_hours
from jsonb_to_recordset($courses$[{"id":"html-intermediate","language_id":"html","level_id":"intermediate","title":"HTML متوسط","slug":"html-intermediate","description":"فرم‌های حرفه‌ای، داده‌های ساختاریافته، دسترس‌پذیری و رسانه در صفحات واقعی.","status":"published","sort_order":2,"estimated_hours":8},{"id":"html-advanced","language_id":"html","level_id":"advanced","title":"HTML پیشرفته","slug":"html-advanced","description":"استانداردهای مدرن HTML، دسترس‌پذیری عمیق، داده ساختاریافته و معماری محتوای حرفه‌ای.","status":"published","sort_order":3,"estimated_hours":10},{"id":"css-intermediate","language_id":"css","level_id":"intermediate","title":"CSS متوسط","slug":"css-intermediate","description":"چیدمان حرفه‌ای با Flexbox و Grid، واکنش‌گرایی، انیمیشن و طراحی رابط کاربری.","status":"published","sort_order":2,"estimated_hours":10},{"id":"css-advanced","language_id":"css","level_id":"advanced","title":"CSS پیشرفته","slug":"css-advanced","description":"معماری CSS، طراحی سیستم، لایه‌های آبشار، بهینه‌سازی و رابط‌های مقیاس‌پذیر.","status":"published","sort_order":3,"estimated_hours":12},{"id":"js-intermediate","language_id":"javascript","level_id":"intermediate","title":"JavaScript متوسط","slug":"javascript-intermediate","description":"DOM، آرایه‌ها و اشیا، رویدادها، فرم‌ها، ذخیره‌سازی و الگوهای کاربردی JavaScript.","status":"published","sort_order":2,"estimated_hours":12},{"id":"js-advanced","language_id":"javascript","level_id":"advanced","title":"JavaScript پیشرفته","slug":"javascript-advanced","description":"برنامه‌نویسی ناهمگام، API، مدیریت خطا، امنیت مرورگر و معماری پروژه‌های واقعی.","status":"published","sort_order":3,"estimated_hours":14}]$courses$::jsonb) as x(
 id text,language_id text,level_id text,title text,slug text,description text,status text,sort_order integer,estimated_hours numeric
)
on conflict(id) do update set title=excluded.title,description=excluded.description,status='published',sort_order=excluded.sort_order,estimated_hours=excluded.estimated_hours,updated_at=now();
insert into public.academy_lessons(id,course_id,title,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,x.course_id,x.title,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"html-intermediate:1","course_id":"html-intermediate","title":"فرم‌های پیشرفته و اعتبارسنجی","summary":"ویژگی‌های required، minlength، maxlength، min، max و pattern اعتبارسنجی اولیه را در مرورگر انجام می‌دهند. برای داده حساس، اعتبارسنجی سمت سرور هم لازم است.","content_html":"<p>ویژگی‌های required، minlength، maxlength، min، max و pattern اعتبارسنجی اولیه را در مرورگر انجام می‌دهند. برای داده حساس، اعتبارسنجی سمت سرور هم لازم است.</p>","starter_code":"<form>\n <label for=\"user\">نام کاربری</label>\n <input id=\"user\" name=\"user\" required minlength=\"3\" maxlength=\"20\" pattern=\"[A-Za-z0-9_]+\">\n <button>ارسال</button>\n</form>","exercise":"فرمی بساز که نام کاربری ۳ تا ۲۰ نویسه‌ای فقط با حروف انگلیسی، عدد و زیرخط بپذیرد.","status":"published","sort_order":1,"estimated_minutes":35},{"id":"html-intermediate:2","course_id":"html-intermediate","title":"گروه‌بندی ورودی‌ها","summary":"fieldset مجموعه‌ای از ورودی‌های مرتبط را گروه‌بندی می‌کند و legend عنوان آن گروه است. این ساختار برای فرم‌های طولانی خواناتر و دسترس‌پذیرتر است.","content_html":"<p>fieldset مجموعه‌ای از ورودی‌های مرتبط را گروه‌بندی می‌کند و legend عنوان آن گروه است. این ساختار برای فرم‌های طولانی خواناتر و دسترس‌پذیرتر است.</p>","starter_code":"<fieldset>\n <legend>اطلاعات تماس</legend>\n <label for=\"email\">ایمیل</label>\n <input id=\"email\" type=\"email\" required>\n</fieldset>","exercise":"فرم ثبت‌نامی با دو گروه «اطلاعات فردی» و «اطلاعات تماس» طراحی کن.","status":"published","sort_order":2,"estimated_minutes":35},{"id":"html-intermediate:3","course_id":"html-intermediate","title":"جدول‌های داده‌ای حرفه‌ای","summary":"برای جدول‌های پیچیده از caption، thead، tbody، tfoot و scope استفاده کن. این عناصر رابطه عنوان ستون‌ها و داده‌ها را برای فناوری‌های کمکی روشن می‌کنند.","content_html":"<p>برای جدول‌های پیچیده از caption، thead، tbody، tfoot و scope استفاده کن. این عناصر رابطه عنوان ستون‌ها و داده‌ها را برای فناوری‌های کمکی روشن می‌کنند.</p>","starter_code":"<table>\n <caption>نتایج آزمون</caption>\n <thead><tr><th scope=\"col\">نام</th><th scope=\"col\">نمره</th></tr></thead>\n <tbody><tr><th scope=\"row\">سارا</th><td>92</td></tr></tbody>\n <tfoot><tr><td>میانگین</td><td>92</td></tr></tfoot>\n</table>","exercise":"جدول نمرات سه دانش‌آموز با عنوان، سرستون و ردیف پایانی میانگین بساز.","status":"published","sort_order":3,"estimated_minutes":35},{"id":"html-intermediate:4","course_id":"html-intermediate","title":"عناصر تعاملی details و dialog","summary":"details و summary یک بخش باز و بسته‌شونده بومی می‌سازند. dialog برای پنجره محاوره‌ای مناسب است و با JavaScript باز و بسته می‌شود.","content_html":"<p>details و summary یک بخش باز و بسته‌شونده بومی می‌سازند. dialog برای پنجره محاوره‌ای مناسب است و با JavaScript باز و بسته می‌شود.</p>","starter_code":"<details>\n <summary>شرایط استفاده</summary>\n <p>متن شرایط اینجا قرار می‌گیرد.</p>\n</details>","exercise":"بخش پرسش‌های متداول با سه عنصر details و summary بساز.","status":"published","sort_order":4,"estimated_minutes":35},{"id":"html-intermediate:5","course_id":"html-intermediate","title":"تصاویر واکنش‌گرا با picture","summary":"عنصر picture اجازه می‌دهد با source و media تصویر مناسب اندازه نمایشگر انتخاب شود. img همچنان باید عنصر پایانی و دارای alt باشد.","content_html":"<p>عنصر picture اجازه می‌دهد با source و media تصویر مناسب اندازه نمایشگر انتخاب شود. img همچنان باید عنصر پایانی و دارای alt باشد.</p>","starter_code":"<picture>\n <source media=\"(max-width:600px)\" srcset=\"small.webp\">\n <source type=\"image/webp\" srcset=\"large.webp\">\n <img src=\"large.jpg\" alt=\"نمای شهر\">\n</picture>","exercise":"برای موبایل و دسکتاپ دو تصویر متفاوت تعریف کن و fallback با img داشته باش.","status":"published","sort_order":5,"estimated_minutes":35},{"id":"html-intermediate:6","course_id":"html-intermediate","title":"ویدیو و زیرنویس","summary":"عنصر track فایل زیرنویس WebVTT را به ویدیو متصل می‌کند. زیرنویس، دسترس‌پذیری و فهم محتوا را در محیط‌های مختلف بهتر می‌کند.","content_html":"<p>عنصر track فایل زیرنویس WebVTT را به ویدیو متصل می‌کند. زیرنویس، دسترس‌پذیری و فهم محتوا را در محیط‌های مختلف بهتر می‌کند.</p>","starter_code":"<video controls width=\"480\">\n <source src=\"lesson.mp4\" type=\"video/mp4\">\n <track src=\"fa.vtt\" kind=\"subtitles\" srclang=\"fa\" label=\"فارسی\" default>\n</video>","exercise":"یک ویدیو با منبع MP4 و زیرنویس فارسی به صفحه اضافه کن.","status":"published","sort_order":6,"estimated_minutes":35},{"id":"html-intermediate:7","course_id":"html-intermediate","title":"SEO معنایی و متادیتا","summary":"عنوان یکتا، توضیح متا، زبان صفحه و ساختار عنوان‌ها به موتورهای جست‌وجو و کاربران کمک می‌کنند. متادیتا جای محتوای باکیفیت و لینک‌های قابل خزیدن را نمی‌گیرد.","content_html":"<p>عنوان یکتا، توضیح متا، زبان صفحه و ساختار عنوان‌ها به موتورهای جست‌وجو و کاربران کمک می‌کنند. متادیتا جای محتوای باکیفیت و لینک‌های قابل خزیدن را نمی‌گیرد.</p>","starter_code":"<head>\n <title>آموزش HTML | آکادمی</title>\n <meta name=\"description\" content=\"آموزش عملی HTML\">\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n</head>","exercise":"برای یک مقاله آموزشی title و description مناسب و یکتا بنویس.","status":"published","sort_order":7,"estimated_minutes":35},{"id":"html-intermediate:8","course_id":"html-intermediate","title":"پروژه: صفحه مقاله دسترس‌پذیر","summary":"در پروژه واقعی، ساختار معنایی، فرم جست‌وجو، تصویر دارای alt، زمان انتشار و بخش محتوای اصلی را کنار هم قرار می‌دهیم.","content_html":"<p>در پروژه واقعی، ساختار معنایی، فرم جست‌وجو، تصویر دارای alt، زمان انتشار و بخش محتوای اصلی را کنار هم قرار می‌دهیم.</p>","starter_code":"<article>\n <header><h1>راهنمای شروع وب</h1><time datetime=\"2026-11-07\">۷ نوامبر ۲۰۲۶</time></header>\n <figure><img src=\"web.jpg\" alt=\"نمایی از کدنویسی\"><figcaption>شروع مسیر وب</figcaption></figure>\n <main><p>متن مقاله...</p></main>\n</article>","exercise":"یک صفحه مقاله کامل با header، article، time، figure، figcaption و بخش محتوای اصلی بساز.","status":"published","sort_order":8,"estimated_minutes":35},{"id":"html-advanced:1","course_id":"html-advanced","title":"الگوی سند و ساختار landmark","summary":"ساختار landmark مانند header، nav، main و footer به کاربران صفحه‌خوان امکان پرش سریع می‌دهد. در هر صفحه معمولاً یک main اصلی داشته باش.","content_html":"<p>ساختار landmark مانند header، nav، main و footer به کاربران صفحه‌خوان امکان پرش سریع می‌دهد. در هر صفحه معمولاً یک main اصلی داشته باش.</p>","starter_code":"<header>...</header>\n<nav aria-label=\"ناوبری اصلی\">...</nav>\n<main id=\"main-content\">...</main>\n<footer>...</footer>","exercise":"برای یک داشبورد، landmarkهای معنایی و لینک پرش به محتوای اصلی تعریف کن.","status":"published","sort_order":1,"estimated_minutes":35},{"id":"html-advanced:2","course_id":"html-advanced","title":"ARIA: نقش و نام قابل دسترس","summary":"ARIA زمانی استفاده می‌شود که HTML بومی به‌تنهایی معنای لازم را منتقل نکند. اولویت با عنصر بومی است؛ نقش‌های تکراری یا نادرست می‌توانند دسترس‌پذیری را خراب کنند.","content_html":"<p>ARIA زمانی استفاده می‌شود که HTML بومی به‌تنهایی معنای لازم را منتقل نکند. اولویت با عنصر بومی است؛ نقش‌های تکراری یا نادرست می‌توانند دسترس‌پذیری را خراب کنند.</p>","starter_code":"<button aria-expanded=\"false\" aria-controls=\"menu\">نمایش منو</button>\n<nav id=\"menu\" hidden>...</nav>","exercise":"یک دکمه منوی بازشو با aria-expanded و aria-controls بساز؛ مقدار expanded باید هنگام باز و بسته‌شدن هماهنگ شود.","status":"published","sort_order":2,"estimated_minutes":35},{"id":"html-advanced:3","course_id":"html-advanced","title":"مدیریت فوکوس و صفحه‌کلید","summary":"تمام کنترل‌های تعاملی باید با صفحه‌کلید قابل استفاده باشند. ترتیب Tab منطقی، focus قابل مشاهده و امکان خروج از پنجره‌های محاوره‌ای ضروری است.","content_html":"<p>تمام کنترل‌های تعاملی باید با صفحه‌کلید قابل استفاده باشند. ترتیب Tab منطقی، focus قابل مشاهده و امکان خروج از پنجره‌های محاوره‌ای ضروری است.</p>","starter_code":"<a href=\"#main\">رفتن به محتوا</a>\n<main id=\"main\" tabindex=\"-1\">محتوا</main>\n<style>:focus-visible{outline:3px solid #e33}</style>","exercise":"یک صفحه را فقط با Tab، Shift+Tab و Enter آزمایش و هر مانع صفحه‌کلید را اصلاح کن.","status":"published","sort_order":3,"estimated_minutes":35},{"id":"html-advanced:4","course_id":"html-advanced","title":"داده ساختاریافته JSON-LD","summary":"داده ساختاریافته اطلاعات صفحه را به قالبی قابل فهم برای موتورهای جست‌وجو تبدیل می‌کند. فقط داده‌ای را اعلام کن که واقعاً در صفحه وجود دارد.","content_html":"<p>داده ساختاریافته اطلاعات صفحه را به قالبی قابل فهم برای موتورهای جست‌وجو تبدیل می‌کند. فقط داده‌ای را اعلام کن که واقعاً در صفحه وجود دارد.</p>","starter_code":"<script type=\"application/ld+json\">\n{\"@context\":\"https://schema.org\",\"@type\":\"Course\",\"name\":\"HTML پیشرفته\",\"provider\":{\"@type\":\"Organization\",\"name\":\"NEXORA FORGE\"}}\n</script>","exercise":"برای یک دوره واقعی، JSON-LD از نوع Course بنویس و نام و ارائه‌دهنده را با محتوای صفحه تطبیق بده.","status":"published","sort_order":4,"estimated_minutes":35},{"id":"html-advanced:5","course_id":"html-advanced","title":"امنیت لینک‌ها و محتوای تعبیه‌شده","summary":"برای لینک خارجی با target=_blank از rel=\"noopener noreferrer\" استفاده کن. برای iframe عنوان روشن و در صورت نیاز sandbox با حداقل مجوزها تعیین کن.","content_html":"<p>برای لینک خارجی با target=_blank از rel=\"noopener noreferrer\" استفاده کن. برای iframe عنوان روشن و در صورت نیاز sandbox با حداقل مجوزها تعیین کن.</p>","starter_code":"<a href=\"https://example.com\" target=\"_blank\" rel=\"noopener noreferrer\">منبع</a>\n<iframe src=\"https://example.com\" title=\"نمایش نمونه\" sandbox></iframe>","exercise":"یک iframe محدود و یک لینک خارجی امن در صفحه نمونه قرار بده.","status":"published","sort_order":5,"estimated_minutes":35},{"id":"html-advanced:6","course_id":"html-advanced","title":"بارگذاری تنبل و اولویت منابع","summary":"loading=\"lazy\" برای رسانه‌های خارج از دید اولیه مفید است. تصویر اصلی بالای صفحه معمولاً نباید lazy باشد. width و height به کاهش جابه‌جایی چیدمان کمک می‌کنند.","content_html":"<p>loading=\"lazy\" برای رسانه‌های خارج از دید اولیه مفید است. تصویر اصلی بالای صفحه معمولاً نباید lazy باشد. width و height به کاهش جابه‌جایی چیدمان کمک می‌کنند.</p>","starter_code":"<img src=\"gallery.webp\" alt=\"گالری\" width=\"800\" height=\"500\" loading=\"lazy\">\n<img src=\"hero.webp\" alt=\"تصویر اصلی\" width=\"1200\" height=\"700\" fetchpriority=\"high\">","exercise":"در صفحه‌ای با چند تصویر، بارگذاری تنبل را برای تصاویر پایین صفحه و اولویت بالا را فقط برای تصویر اصلی تنظیم کن.","status":"published","sort_order":6,"estimated_minutes":35},{"id":"html-advanced:7","course_id":"html-advanced","title":"قالب‌های HTML و template","summary":"عنصر template محتوایی نگه می‌دارد که تا زمان تکثیر با JavaScript نمایش داده نمی‌شود. برای کارت‌های تکراری می‌توان از آن استفاده کرد.","content_html":"<p>عنصر template محتوایی نگه می‌دارد که تا زمان تکثیر با JavaScript نمایش داده نمی‌شود. برای کارت‌های تکراری می‌توان از آن استفاده کرد.</p>","starter_code":"<template id=\"card-template\">\n <article class=\"card\"><h2></h2><p></p></article>\n</template>","exercise":"یک template برای کارت درس بساز و با JavaScript دو کارت از آن تولید کن.","status":"published","sort_order":7,"estimated_minutes":35},{"id":"html-advanced:8","course_id":"html-advanced","title":"پروژه نهایی: صفحه دوره استاندارد","summary":"در پروژه نهایی، metadata، landmarkها، داده ساختاریافته، رسانه واکنش‌گرا و اجزای دسترس‌پذیر کنار هم قرار می‌گیرند. کیفیت را با اعتبارسنج HTML و آزمون صفحه‌کلید بررسی کن.","content_html":"<p>در پروژه نهایی، metadata، landmarkها، داده ساختاریافته، رسانه واکنش‌گرا و اجزای دسترس‌پذیر کنار هم قرار می‌گیرند. کیفیت را با اعتبارسنج HTML و آزمون صفحه‌کلید بررسی کن.</p>","starter_code":"<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>دوره وب</title></head>\n<body><header><nav aria-label=\"اصلی\">...</nav></header><main><article><h1>دوره وب</h1></article></main><footer>...</footer></body>\n</html>","exercise":"یک صفحه معرفی دوره بساز و آن را با اعتبارسنج HTML، صفحه‌کلید و صفحه‌خوان بررسی کن.","status":"published","sort_order":8,"estimated_minutes":35},{"id":"css-intermediate:1","course_id":"css-intermediate","title":"Flexbox: محور و تراز","summary":"Flexbox برای چیدمان یک‌بعدی است. flex-direction محور اصلی را تعیین می‌کند؛ justify-content روی محور اصلی و align-items روی محور متقاطع اثر می‌گذارد.","content_html":"<p>Flexbox برای چیدمان یک‌بعدی است. flex-direction محور اصلی را تعیین می‌کند؛ justify-content روی محور اصلی و align-items روی محور متقاطع اثر می‌گذارد.</p>","starter_code":".toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px}","exercise":"نوار ناوبری بساز که لوگو در یک سمت و لینک‌ها در سمت دیگر قرار بگیرند.","status":"published","sort_order":1,"estimated_minutes":35},{"id":"css-intermediate:2","course_id":"css-intermediate","title":"Flex grow، shrink و basis","summary":"سه ویژگی flex-grow، flex-shrink و flex-basis تعیین می‌کنند آیتم‌ها چگونه فضای آزاد را تقسیم یا فشرده کنند. shorthand flex نوشتن آن‌ها را ساده می‌کند.","content_html":"<p>سه ویژگی flex-grow، flex-shrink و flex-basis تعیین می‌کنند آیتم‌ها چگونه فضای آزاد را تقسیم یا فشرده کنند. shorthand flex نوشتن آن‌ها را ساده می‌کند.</p>","starter_code":".main{flex:2 1 320px}.side{flex:1 1 220px}","exercise":"یک چیدمان دو ستونه بساز که ستون اصلی دو برابر ستون کناری رشد کند.","status":"published","sort_order":2,"estimated_minutes":35},{"id":"css-intermediate:3","course_id":"css-intermediate","title":"CSS Grid و شبکه‌های منعطف","summary":"Grid برای چیدمان دوبعدی مناسب است. repeat، minmax و auto-fit شبکه‌ای می‌سازند که بدون تعداد breakpoint زیاد با عرض صفحه تطبیق پیدا می‌کند.","content_html":"<p>Grid برای چیدمان دوبعدی مناسب است. repeat، minmax و auto-fit شبکه‌ای می‌سازند که بدون تعداد breakpoint زیاد با عرض صفحه تطبیق پیدا می‌کند.</p>","starter_code":".cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}","exercise":"گالری کارت‌هایی بساز که در فضای موجود خودکار یک تا چند ستون شوند.","status":"published","sort_order":3,"estimated_minutes":35},{"id":"css-intermediate:4","course_id":"css-intermediate","title":"چیدمان Grid با نواحی","summary":"grid-template-areas نام‌گذاری نواحی چیدمان را خواناتر می‌کند و در media query می‌توان نقشه موبایل را تغییر داد.","content_html":"<p>grid-template-areas نام‌گذاری نواحی چیدمان را خواناتر می‌کند و در media query می‌توان نقشه موبایل را تغییر داد.</p>","starter_code":".layout{display:grid;grid-template-areas:'head head' 'side main' 'foot foot';grid-template-columns:240px 1fr}\n.header{grid-area:head}.sidebar{grid-area:side}.content{grid-area:main}.footer{grid-area:foot}","exercise":"صفحه‌ای با سربرگ، منو، محتوا و پابرگ بساز و در موبایل منو را بالای محتوا بیاور.","status":"published","sort_order":4,"estimated_minutes":35},{"id":"css-intermediate:5","course_id":"css-intermediate","title":"Media Query و طراحی موبایل‌اول","summary":"در روش mobile-first ابتدا استایل پایه برای صفحه کوچک نوشته می‌شود و سپس با min-width امکانات چیدمان بزرگ‌تر اضافه می‌شوند.","content_html":"<p>در روش mobile-first ابتدا استایل پایه برای صفحه کوچک نوشته می‌شود و سپس با min-width امکانات چیدمان بزرگ‌تر اضافه می‌شوند.</p>","starter_code":".wrap{padding:16px}\n@media(min-width:700px){.wrap{max-width:1100px;margin:auto;padding:32px}}","exercise":"یک کارت محصول را ابتدا برای موبایل طراحی کن و در نمایشگر بزرگ‌تر سه ستونه کن.","status":"published","sort_order":5,"estimated_minutes":35},{"id":"css-intermediate:6","course_id":"css-intermediate","title":"واحدهای پویا و clamp","summary":"clamp(min, preferred, max) اندازه‌ای منعطف با حداقل و حداکثر می‌سازد. واحدهای vw و درصد باید با محدودیت مناسب استفاده شوند.","content_html":"<p>clamp(min, preferred, max) اندازه‌ای منعطف با حداقل و حداکثر می‌سازد. واحدهای vw و درصد باید با محدودیت مناسب استفاده شوند.</p>","starter_code":"h1{font-size:clamp(1.8rem,4vw,3.5rem)}\n.container{width:min(92%,1100px);margin:auto}","exercise":"اندازه عنوان و عرض محتوای صفحه را با clamp و min تنظیم کن.","status":"published","sort_order":6,"estimated_minutes":35},{"id":"css-intermediate:7","course_id":"css-intermediate","title":"حالت‌های تعاملی و focus-visible","summary":"حالت hover برای اشاره‌گر و focus-visible برای ناوبری صفحه‌کلید است. حذف outline بدون جایگزین مناسب، تجربه کاربران صفحه‌کلید را مختل می‌کند.","content_html":"<p>حالت hover برای اشاره‌گر و focus-visible برای ناوبری صفحه‌کلید است. حذف outline بدون جایگزین مناسب، تجربه کاربران صفحه‌کلید را مختل می‌کند.</p>","starter_code":".btn:hover{transform:translateY(-2px)}\n.btn:focus-visible{outline:3px solid #f44;outline-offset:3px}","exercise":"برای دکمه سه حالت عادی، hover و focus-visible با کنتراست واضح طراحی کن.","status":"published","sort_order":7,"estimated_minutes":35},{"id":"css-intermediate:8","course_id":"css-intermediate","title":"Transition و keyframes","summary":"transition تغییر حالت را نرم می‌کند؛ @keyframes برای توالی چندمرحله‌ای است. انیمیشن باید کوتاه، هدفمند و قابل کاهش برای کاربران حساس به حرکت باشد.","content_html":"<p>transition تغییر حالت را نرم می‌کند؛ @keyframes برای توالی چندمرحله‌ای است. انیمیشن باید کوتاه، هدفمند و قابل کاهش برای کاربران حساس به حرکت باشد.</p>","starter_code":".card{transition:transform .2s ease}\n.card:hover{transform:translateY(-4px)}\n@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}","exercise":"برای کارت hover نرم بساز و prefers-reduced-motion را پشتیبانی کن.","status":"published","sort_order":8,"estimated_minutes":35},{"id":"css-advanced:1","course_id":"css-advanced","title":"معماری CSS و نام‌گذاری BEM","summary":"BEM کلاس‌ها را به block، element و modifier تقسیم می‌کند تا وابستگی و تداخل سبک‌ها کاهش یابد. قرارداد نام‌گذاری باید در کل پروژه ثابت بماند.","content_html":"<p>BEM کلاس‌ها را به block، element و modifier تقسیم می‌کند تا وابستگی و تداخل سبک‌ها کاهش یابد. قرارداد نام‌گذاری باید در کل پروژه ثابت بماند.</p>","starter_code":".card{}.card__title{}.card--featured{}","exercise":"برای کارت محصول، نام‌گذاری BEM شامل عنوان، تصویر و حالت ویژه طراحی کن.","status":"published","sort_order":1,"estimated_minutes":35},{"id":"css-advanced:2","course_id":"css-advanced","title":"Cascade Layers","summary":"@layer ترتیب اولویت لایه‌های آبشار را مشخص می‌کند و مدیریت reset، پایه، اجزا و اصلاحات را آسان‌تر می‌سازد.","content_html":"<p>@layer ترتیب اولویت لایه‌های آبشار را مشخص می‌کند و مدیریت reset، پایه، اجزا و اصلاحات را آسان‌تر می‌سازد.</p>","starter_code":"@layer reset,base,components,utilities;\n@layer components{.button{padding:12px;border-radius:8px}}\n@layer utilities{.hidden{display:none}}","exercise":"چهار لایه برای یک پروژه تعریف کن و نشان بده ترتیب آن‌ها چگونه تعارض را حل می‌کند.","status":"published","sort_order":2,"estimated_minutes":35},{"id":"css-advanced:3","course_id":"css-advanced","title":"متغیرهای CSS و تم پویا","summary":"custom properties می‌توانند در سطح ریشه یا یک جزء تعریف شوند. با تغییر attribute می‌توان تم روشن و تاریک را بدون تکرار قواعد ساخت.","content_html":"<p>custom properties می‌توانند در سطح ریشه یا یک جزء تعریف شوند. با تغییر attribute می‌توان تم روشن و تاریک را بدون تکرار قواعد ساخت.</p>","starter_code":":root{--bg:#fff;--text:#171717}\n[data-theme=\"dark\"]{--bg:#111;--text:#f5f5f5}\nbody{background:var(--bg);color:var(--text)}","exercise":"دو تم روشن و تاریک با متغیرهای CSS بساز و با تغییر data-theme جابه‌جا کن.","status":"published","sort_order":3,"estimated_minutes":35},{"id":"css-advanced:4","course_id":"css-advanced","title":"Container Queries","summary":"Container Query سبک یک جزء را بر اساس اندازه ظرف خودش تغییر می‌دهد، نه فقط اندازه viewport. این روش برای کارت‌های قابل استفاده مجدد مناسب است.","content_html":"<p>Container Query سبک یک جزء را بر اساس اندازه ظرف خودش تغییر می‌دهد، نه فقط اندازه viewport. این روش برای کارت‌های قابل استفاده مجدد مناسب است.</p>","starter_code":".card-wrap{container-type:inline-size}\n@container (min-width:500px){.card{display:grid;grid-template-columns:1fr 2fr}}","exercise":"کارتی بساز که وقتی ظرفش عریض شد تصویر و متن در دو ستون قرار گیرند.","status":"published","sort_order":4,"estimated_minutes":35},{"id":"css-advanced:5","course_id":"css-advanced","title":"توابع مدرن CSS","summary":"توابع min، max، clamp، calc و minmax برای ساخت اندازه‌های منعطف به کار می‌روند. ترکیب آن‌ها می‌تواند breakpointهای غیرضروری را کاهش دهد.","content_html":"<p>توابع min، max، clamp، calc و minmax برای ساخت اندازه‌های منعطف به کار می‌روند. ترکیب آن‌ها می‌تواند breakpointهای غیرضروری را کاهش دهد.</p>","starter_code":".page{width:min(100% - 2rem,1200px);margin-inline:auto}\n.title{font-size:clamp(2rem,5vw,4rem)}","exercise":"عرض صفحه و اندازه عنوان را بدون overflow در موبایل و دسکتاپ تنظیم کن.","status":"published","sort_order":5,"estimated_minutes":35},{"id":"css-advanced:6","course_id":"css-advanced","title":"Logical Properties و چندجهته","summary":"ویژگی‌های منطقی مانند margin-inline و padding-block مستقل از چپ‌به‌راست یا راست‌به‌چپ هستند و ساخت رابط چندزبانه را آسان می‌کنند.","content_html":"<p>ویژگی‌های منطقی مانند margin-inline و padding-block مستقل از چپ‌به‌راست یا راست‌به‌چپ هستند و ساخت رابط چندزبانه را آسان می‌کنند.</p>","starter_code":".card{padding-block:20px;padding-inline:24px;border-inline-start:3px solid crimson}","exercise":"یک کارت بساز که در هر دو جهت RTL و LTR درست نمایش داده شود.","status":"published","sort_order":6,"estimated_minutes":35},{"id":"css-advanced:7","course_id":"css-advanced","title":"بهینه‌سازی رندر و پایداری چیدمان","summary":"از انتخابگرهای بیش از حد پیچیده، انیمیشن ویژگی‌های پرهزینه و تغییر ناگهانی ابعاد جلوگیری کن. برای تصاویر ابعاد مشخص تعیین کن و از transform برای حرکت استفاده کن.","content_html":"<p>از انتخابگرهای بیش از حد پیچیده، انیمیشن ویژگی‌های پرهزینه و تغییر ناگهانی ابعاد جلوگیری کن. برای تصاویر ابعاد مشخص تعیین کن و از transform برای حرکت استفاده کن.</p>","starter_code":"img{display:block;max-width:100%;height:auto}\n.panel{content-visibility:auto;contain-intrinsic-size:500px}","exercise":"یک صفحه طولانی را بررسی و جابه‌جایی چیدمان و هزینه رندر آن را کاهش بده.","status":"published","sort_order":7,"estimated_minutes":35},{"id":"css-advanced:8","course_id":"css-advanced","title":"پروژه نهایی: Design System","summary":"یک design system کوچک شامل توکن‌های رنگ و فاصله، دکمه‌ها، کارت‌ها، فرم‌ها، تم تاریک و قواعد واکنش‌گرا بساز. مستندسازی استفاده از اجزا بخشی از پروژه است.","content_html":"<p>یک design system کوچک شامل توکن‌های رنگ و فاصله، دکمه‌ها، کارت‌ها، فرم‌ها، تم تاریک و قواعد واکنش‌گرا بساز. مستندسازی استفاده از اجزا بخشی از پروژه است.</p>","starter_code":"@layer tokens,base,components,utilities;\n@layer tokens{:root{--brand:#d9273b;--space:1rem;--radius:12px}}\n@layer components{.button{background:var(--brand);padding:var(--space);border-radius:var(--radius)}}","exercise":"یک کتابخانه رابط کوچک با حداقل سه جزء، دو تم و قواعد دسترس‌پذیری تحویل بده.","status":"published","sort_order":8,"estimated_minutes":35},{"id":"js-intermediate:1","course_id":"js-intermediate","title":"DOM و پیمایش عناصر","summary":"DOM نمایش درختی سند HTML است. querySelector یک عنصر و querySelectorAll مجموعه‌ای از عناصر مطابق انتخابگر را برمی‌گرداند.","content_html":"<p>DOM نمایش درختی سند HTML است. querySelector یک عنصر و querySelectorAll مجموعه‌ای از عناصر مطابق انتخابگر را برمی‌گرداند.</p>","starter_code":"const title=document.querySelector('h1');\ntitle.textContent='عنوان جدید';\nconst items=document.querySelectorAll('.item');\nconsole.log(items.length);","exercise":"سه عنصر را با انتخابگرهای متفاوت پیدا کن و متن یکی را تغییر بده.","status":"published","sort_order":1,"estimated_minutes":35},{"id":"js-intermediate:2","course_id":"js-intermediate","title":"ساخت و حذف عناصر","summary":"با createElement عنصر جدید می‌سازیم، textContent متن امن اضافه می‌کند و append آن را به DOM می‌افزاید. برای حذف از remove استفاده کن.","content_html":"<p>با createElement عنصر جدید می‌سازیم، textContent متن امن اضافه می‌کند و append آن را به DOM می‌افزاید. برای حذف از remove استفاده کن.</p>","starter_code":"const li=document.createElement('li');\nli.textContent='درس جدید';\ndocument.querySelector('ul').append(li);","exercise":"فهرست وظایف بساز که با کلیک دکمه یک مورد جدید اضافه کند.","status":"published","sort_order":2,"estimated_minutes":35},{"id":"js-intermediate:3","course_id":"js-intermediate","title":"رویدادها و event delegation","summary":"به‌جای افزودن شنونده به تک‌تک فرزندان، می‌توان یک شنونده روی والد گذاشت و با event.target عنصر موردنظر را تشخیص داد.","content_html":"<p>به‌جای افزودن شنونده به تک‌تک فرزندان، می‌توان یک شنونده روی والد گذاشت و با event.target عنصر موردنظر را تشخیص داد.</p>","starter_code":"document.querySelector('ul').addEventListener('click',e=>{\n if(e.target.matches('button.remove')) e.target.closest('li').remove();\n});","exercise":"برای فهرستی از آیتم‌ها حذف هر مورد را با event delegation پیاده‌سازی کن.","status":"published","sort_order":3,"estimated_minutes":35},{"id":"js-intermediate:4","course_id":"js-intermediate","title":"آرایه‌ها: map، filter و reduce","summary":"map داده‌ها را تبدیل می‌کند، filter موارد مطابق شرط را نگه می‌دارد و reduce آن‌ها را به یک مقدار خلاصه می‌کند. این متدها آرایه اصلی را تغییر نمی‌دهند.","content_html":"<p>map داده‌ها را تبدیل می‌کند، filter موارد مطابق شرط را نگه می‌دارد و reduce آن‌ها را به یک مقدار خلاصه می‌کند. این متدها آرایه اصلی را تغییر نمی‌دهند.</p>","starter_code":"const scores=[45,70,90];\nconst passed=scores.filter(x=>x>=50);\nconst doubled=scores.map(x=>x*2);\nconst total=scores.reduce((a,b)=>a+b,0);","exercise":"از آرایه نمرات، قبول‌شده‌ها، نمره‌های دوبرابر و میانگین را محاسبه کن.","status":"published","sort_order":4,"estimated_minutes":35},{"id":"js-intermediate:5","course_id":"js-intermediate","title":"اشیاء و destructuring","summary":"Object داده‌های مرتبط را با کلید نگه می‌دارد. destructuring مقادیر را در متغیرهای جدا می‌ریزد و spread برای ساخت کپی سطحی کاربرد دارد.","content_html":"<p>Object داده‌های مرتبط را با کلید نگه می‌دارد. destructuring مقادیر را در متغیرهای جدا می‌ریزد و spread برای ساخت کپی سطحی کاربرد دارد.</p>","starter_code":"const student={name:'Sara',level:'intermediate'};\nconst {name,level}=student;\nconst updated={...student,level:'advanced'};","exercise":"شیء دانش‌آموز بساز، دو ویژگی را destructure کن و یک نسخه به‌روزشده بساز.","status":"published","sort_order":5,"estimated_minutes":35},{"id":"js-intermediate:6","course_id":"js-intermediate","title":"ماژول‌ها و جداسازی کد","summary":"export و import کد را به فایل‌های مستقل تقسیم می‌کنند. type=\"module\" در مرورگر برای بارگذاری ماژول لازم است و فایل‌ها باید از سرور اجرا شوند.","content_html":"<p>export و import کد را به فایل‌های مستقل تقسیم می‌کنند. type=\"module\" در مرورگر برای بارگذاری ماژول لازم است و فایل‌ها باید از سرور اجرا شوند.</p>","starter_code":"// math.js\nexport const add=(a,b)=>a+b;\n// app.js\nimport {add} from './math.js';\nconsole.log(add(2,3));","exercise":"توابع محاسباتی را در یک فایل جدا export و در فایل اصلی import کن.","status":"published","sort_order":6,"estimated_minutes":35},{"id":"js-intermediate:7","course_id":"js-intermediate","title":"فرم‌ها و اعتبارسنجی سمت کاربر","summary":"رویداد submit را کنترل کن، از ارسال پیش‌فرض جلوگیری کن و مقدارها را بررسی کن. اعتبارسنجی مرورگر جای اعتبارسنجی سرور را نمی‌گیرد.","content_html":"<p>رویداد submit را کنترل کن، از ارسال پیش‌فرض جلوگیری کن و مقدارها را بررسی کن. اعتبارسنجی مرورگر جای اعتبارسنجی سرور را نمی‌گیرد.</p>","starter_code":"form.addEventListener('submit',e=>{\n e.preventDefault();\n const value=input.value.trim();\n if(value.length<3){message.textContent='حداقل سه نویسه';return;}\n message.textContent='معتبر است';\n});","exercise":"فرم نام بساز که ورودی خالی یا کوتاه را نپذیرد و پیام خطا نشان دهد.","status":"published","sort_order":7,"estimated_minutes":35},{"id":"js-intermediate:8","course_id":"js-intermediate","title":"localStorage و JSON","summary":"localStorage فقط رشته ذخیره می‌کند؛ برای داده ساختاریافته از JSON.stringify و JSON.parse استفاده کن. داده حساس مانند رمز عبور را در آن ذخیره نکن.","content_html":"<p>localStorage فقط رشته ذخیره می‌کند؛ برای داده ساختاریافته از JSON.stringify و JSON.parse استفاده کن. داده حساس مانند رمز عبور را در آن ذخیره نکن.</p>","starter_code":"const tasks=['HTML','CSS'];\nlocalStorage.setItem('tasks',JSON.stringify(tasks));\nconst saved=JSON.parse(localStorage.getItem('tasks')||'[]');","exercise":"فهرست کارها را ذخیره کن تا پس از بارگذاری دوباره صفحه باقی بماند.","status":"published","sort_order":8,"estimated_minutes":35},{"id":"js-advanced:1","course_id":"js-advanced","title":"Execution Context و Scope","summary":"JavaScript برای هر فراخوانی محیط اجرا ایجاد می‌کند. scope تعیین می‌کند متغیر کجا قابل دسترسی باشد. let و const دارای block scope هستند.","content_html":"<p>JavaScript برای هر فراخوانی محیط اجرا ایجاد می‌کند. scope تعیین می‌کند متغیر کجا قابل دسترسی باشد. let و const دارای block scope هستند.</p>","starter_code":"const globalName='NEXORA';\nfunction show(){\n const localName='Academy';\n return globalName+' '+localName;\n}\nconsole.log(show());","exercise":"با تابع‌های تو در تو تفاوت global، function و block scope را آزمایش کن.","status":"published","sort_order":1,"estimated_minutes":35},{"id":"js-advanced:2","course_id":"js-advanced","title":"Closure و کاربرد آن","summary":"Closure زمانی رخ می‌دهد که تابع به متغیرهای محیط بیرونی خود دسترسی را حفظ کند. این الگو برای ساخت state خصوصی و تابع‌های پیکربندی کاربرد دارد.","content_html":"<p>Closure زمانی رخ می‌دهد که تابع به متغیرهای محیط بیرونی خود دسترسی را حفظ کند. این الگو برای ساخت state خصوصی و تابع‌های پیکربندی کاربرد دارد.</p>","starter_code":"function createCounter(){\n let count=0;\n return ()=>++count;\n}\nconst next=createCounter();\nconsole.log(next(),next());","exercise":"تابعی بساز که شمارنده خصوصی داشته باشد و فقط از طریق تابع بازگشتی تغییر کند.","status":"published","sort_order":2,"estimated_minutes":35},{"id":"js-advanced:3","course_id":"js-advanced","title":"پروتوتایپ و کلاس‌ها","summary":"اشیا می‌توانند ویژگی‌ها و متدها را از prototype به ارث ببرند. class نحو ساده‌تری برای تعریف سازنده و متدها فراهم می‌کند.","content_html":"<p>اشیا می‌توانند ویژگی‌ها و متدها را از prototype به ارث ببرند. class نحو ساده‌تری برای تعریف سازنده و متدها فراهم می‌کند.</p>","starter_code":"class Course{\n constructor(name){this.name=name;}\n describe(){return `دوره ${this.name}`;}\n}\nconst html=new Course('HTML');","exercise":"کلاس Course با متد معرفی و کلاس فرزند برای دوره آنلاین بساز.","status":"published","sort_order":3,"estimated_minutes":35},{"id":"js-advanced:4","course_id":"js-advanced","title":"Promise و زنجیره‌سازی","summary":"Promise نماینده نتیجه آینده یک عملیات است. then برای نتیجه، catch برای خطا و finally برای پاک‌سازی مستقل از نتیجه استفاده می‌شوند.","content_html":"<p>Promise نماینده نتیجه آینده یک عملیات است. then برای نتیجه، catch برای خطا و finally برای پاک‌سازی مستقل از نتیجه استفاده می‌شوند.</p>","starter_code":"const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));\nwait(500).then(()=>console.log('تمام شد')).catch(console.error);","exercise":"یک Promise بساز که پس از تأخیر کوتاه مقدار برگرداند و خطای احتمالی آن مدیریت شود.","status":"published","sort_order":4,"estimated_minutes":35},{"id":"js-advanced:5","course_id":"js-advanced","title":"async و await","summary":"async تابعی می‌سازد که Promise برمی‌گرداند. await اجرای همان تابع را تا تعیین تکلیف Promise متوقف می‌کند؛ خطا را با try/catch مدیریت کن.","content_html":"<p>async تابعی می‌سازد که Promise برمی‌گرداند. await اجرای همان تابع را تا تعیین تکلیف Promise متوقف می‌کند؛ خطا را با try/catch مدیریت کن.</p>","starter_code":"async function load(){\n try{const response=await fetch('/data.json');\n if(!response.ok)throw new Error('خطای پاسخ');\n return await response.json();}\n catch(error){console.error(error);}\n}","exercise":"تابعی بنویس که JSON را از API بگیرد، پاسخ ناموفق را تشخیص دهد و خطا را مدیریت کند.","status":"published","sort_order":5,"estimated_minutes":35},{"id":"js-advanced:6","course_id":"js-advanced","title":"Fetch API و کار با REST","summary":"fetch برای درخواست شبکه است. وضعیت HTTP را با response.ok بررسی کن، داده JSON را بخوان و برای درخواست‌های تغییردهنده از روش و بدنه مناسب استفاده کن.","content_html":"<p>fetch برای درخواست شبکه است. وضعیت HTTP را با response.ok بررسی کن، داده JSON را بخوان و برای درخواست‌های تغییردهنده از روش و بدنه مناسب استفاده کن.</p>","starter_code":"async function getUsers(){\n const res=await fetch('https://jsonplaceholder.typicode.com/users');\n if(!res.ok)throw new Error(`HTTP ${res.status}`);\n return res.json();\n}","exercise":"اطلاعات یک API عمومی را دریافت کن و نام سه نتیجه را در صفحه نمایش بده.","status":"published","sort_order":6,"estimated_minutes":35},{"id":"js-advanced:7","course_id":"js-advanced","title":"امنیت سمت مرورگر","summary":"ورودی کاربر را با innerHTML وارد DOM نکن؛ برای متن از textContent استفاده کن. اسرار و کلیدهای خصوصی نباید در JavaScript سمت مرورگر قرار گیرند.","content_html":"<p>ورودی کاربر را با innerHTML وارد DOM نکن؛ برای متن از textContent استفاده کن. اسرار و کلیدهای خصوصی نباید در JavaScript سمت مرورگر قرار گیرند.</p>","starter_code":"const userText='<img src=x onerror=alert(1)>';\nconst output=document.querySelector('#output');\noutput.textContent=userText;","exercise":"یک نمایشگر پیام بساز که متن HTML واردشده را به‌صورت متن بی‌خطر نشان دهد.","status":"published","sort_order":7,"estimated_minutes":35},{"id":"js-advanced:8","course_id":"js-advanced","title":"مدیریت خطا، Debug و پروژه نهایی","summary":"خطاها را با پیام قابل فهم، وضعیت مناسب و ثبت اطلاعات لازم مدیریت کن. در DevTools از breakpoint و Network برای عیب‌یابی استفاده کن.","content_html":"<p>خطاها را با پیام قابل فهم، وضعیت مناسب و ثبت اطلاعات لازم مدیریت کن. در DevTools از breakpoint و Network برای عیب‌یابی استفاده کن.</p>","starter_code":"async function run(){\n try{const data=await getUsers();\n renderUsers(data);\n }catch(error){\n showMessage('دریافت اطلاعات ناموفق بود');\n console.error(error);\n }\n}","exercise":"یک داشبورد کوچک بساز که داده API را بگیرد، در حالت بارگذاری پیام نشان دهد و خطا و نتیجه را جداگانه نمایش دهد.","status":"published","sort_order":8,"estimated_minutes":35}]$lessons$::jsonb) as x(
 id text,course_id text,title text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer
)
on conflict(id) do update set title=excluded.title,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,updated_at=now();
commit;

-- Expected totals after running:
-- 9 courses, 106 lessons (58 existing beginner + 48 new intermediate/advanced).
select c.id,c.title,c.status,count(l.id) as lesson_count
from public.academy_courses c left join public.academy_lessons l on l.course_id=c.id
 group by c.id,c.title,c.status order by c.sort_order,c.language_id,c.id;
